// Arma el prompt con los resultados del test S0 y las sesiones base S1–S4.
const body = $('Webhook generar-plan').first().json.body;
const semanas = $input.first().json.semanas || [];
const m = Object.fromEntries((body.resultados || []).map(r => [r.codigo, r.valor]));
const base = semanas
  .filter(w => ['S1', 'S2', 'S3', 'S4'].includes(w.id))
  .flatMap(w => w.sesiones.map(s => ({ semana: w.id, num: s.num, nombre: s.name, bloques: s.blocks })));
if (!base.length) throw new Error('No hay plan base T1 para el nivel ' + body.nivel);

const v = k => (m[k] ?? 'ND');
const prompt = `Escalador: ${body.nombre}, rango etario ${body.rangoEtario}, ${body.pesoKg ?? 'ND'} kg, nivel ${body.nivel}.
Resultados del test S0 (protocolo Hörst):
- T2 tracción máxima con lastre: ${v('T2')} kg adicionales
- T4 suspensión 5 seg en 20 mm con lastre: ${v('T4')} kg adicionales
- T5 máximo dominadas seguidas: ${v('T5')} reps
- T6 suspensión máxima sin lastre: ${v('T6')} seg
- T7 campus máximo de movimientos: ${v('T7')}
- T9 abdominales en suspensión: ${v('T9')} reps
- Powerslab: D ${v('PowerslabD')} cm / I ${v('PowerslabI')} cm
- Circuito estándar: ${v('Circuito')} movimientos

Plan base de las semanas S1–S4 (acumulación), en JSON:
${JSON.stringify(base)}

Personaliza esas sesiones para este escalador:
- Conserva EXACTAMENTE las mismas sesiones (semana, num) y los mismos nombres de bloque ("n").
- Ajusta solo los valores de "params": cargas en kg calculadas desde T2/T4 (ej. "40–42,5 kg · 80–85% de tu T2"),
  series y tiempos según su nivel. No inventes ejercicios nuevos.
- Si un dato es ND, deja el parámetro como estaba.
Devuelve SOLO un JSON válido, sin texto adicional, con esta forma:
{"sesiones":[{"semana":"S1","num":1,"nombre":"...","bloques":[{"n":"...","i":"...","params":[["Etiqueta","Valor"]]}]}]}`;

return [{ json: { prompt, escaladorId: body.escaladorId, claves: base.map(b => b.semana + '_' + b.num) } }];

// Extrae el JSON de la respuesta y lo valida contra las sesiones base.
const ctx = $('Preparar prompt').first().json;
const texto = $input.first().json.output ?? $input.first().json.text ?? '';
const match = String(texto).match(/\{[\s\S]*\}/);
if (!match) throw new Error('La respuesta de la AI no contiene JSON');
const parsed = JSON.parse(match[0]);
const validas = new Set(ctx.claves);
const filas = (parsed.sesiones || [])
  .filter(s => validas.has(s.semana + '_' + s.num))
  .filter(s => Array.isArray(s.bloques) && s.bloques.every(b => b && typeof b.n === 'string' && Array.isArray(b.params)))
  .map(s => ({ json: {
    escalador_id: ctx.escaladorId,
    trimestre: 'T1',
    semana: s.semana,
    sesion_num: Number(s.num),
    nombre: String(s.nombre || ''),
    bloques: JSON.stringify(s.bloques),
  }}));
if (!filas.length) throw new Error('La AI no devolvió sesiones válidas');
return filas;
